import type { CampaignUrgency } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';

interface CampaignUrgencyEntry {
  label: string;
  variant: BadgeVariants;
}

export const campaignUrgencyConfig: Record<CampaignUrgency, CampaignUrgencyEntry> = {
  low: { label: 'Low', variant: 'default' },
  normal: { label: 'Normal', variant: 'info' },
  elevated: { label: 'Elevated', variant: 'warning' },
  high: { label: 'High', variant: 'violet' },
  critical: { label: 'Critical', variant: 'destructive' },
};

const defaultEntry: CampaignUrgencyEntry = { label: '', variant: 'default' };

export function getCampaignUrgency(urgency: CampaignUrgency): CampaignUrgencyEntry {
  return campaignUrgencyConfig[urgency] ?? { ...defaultEntry, label: snakeCaseToCapitalizedCase(urgency) };
}

export const campaignUrgencyValues = Object.keys(campaignUrgencyConfig) as [CampaignUrgency, ...CampaignUrgency[]];

export const campaignUrgencyOptions: SelectItem<CampaignUrgency>[] = Object.entries(campaignUrgencyConfig).map(
  ([value, { label }]) => ({ name: label, value: value as CampaignUrgency })
);
